const { vec } = NMath;
const size = 28;
const threshold = 0.1;

const samples = await IO.loadMNIST();

// Every pixel with density above the threshold becomes a point in [0,1]^2 weighted by its density.
const toCloud = image => {
    const points = [];
    const weights = [];
    for (let i = 0; i < size * size; i++) {
        if (image[i] <= threshold) continue;
        points.push(vec((i % size + 0.5) / size, 1 - (Math.floor(i / size) + 0.5) / size));
        weights.push(image[i]);
    }
    if (points.length === 0) throw new Error("The image is empty");
    const total = weights.reduce((sum, w) => sum + w, 0);
    return { points, weights: weights.map(w => w / total) };
};

const plot = IO.plotPointCloud([[0, 0]], { aspect: "equal", radius: 0.012, color: [0.4, 0.4, 0.4] });
const moving = plot.add([[0, 0]], { radius: 0.016, color: [1, 0, 0] });
// Invisible anchors keep the unit square fixed.
plot.add([[-0.1, -0.1], [1.1, 1.1]], { color: [0, 0, 0] });

let ot;
let time = 0;
const showTime = t => {
    if (!ot) return;
    moving.update(ot.interpolate(t), { color: [1 - t, t, 0] });
    plot.render();
};

let first = 0, second = 1;
// Recompute the transport plan between the two selected samples.
const transport = () => {
    const source = toCloud(samples[first]);
    const target = toCloud(samples[second]);
    if (!source || !target) {
        ot = undefined;
        console.warn("A selected image is empty");
        return;
    }
    plot.update(target.points);
    console.log(`Transporting ${source.points.length} points to ${target.points.length} points`);
    ot = OptimalTransport.new(source, target, { entropy: 0.0005, maxIterations: 1000 }).fit();
    console.log(`Sinkhorn iterations: ${ot.iterations}, transport cost: ${ot.cost().toFixed(5)}`);
    showTime(time);
};

const indexSlider = (title, value, onChange) => ({
    type: "slider", value: () => ({
        title, min: 0, max: samples.length - 1, step: 1, value,
        onChange: index => onChange(Math.round(index)),
    })
});

const ui = IO.UI(
    { type: "canvas", value: () => plot },
    indexSlider("first sample:", first, index => { first = index; transport(); }),
    indexSlider("second sample:", second, index => { second = index; transport(); }),
    {
        type: "slider", value: () => ({
            title: "t:", min: 0, max: 1, step: 0.01, value: 0,
            onChange: t => { time = t; showTime(t); },
        })
    },
);
transport();
ui;
